IMPLEMENT_PRIMARY_GAME_MODULE(FDefaultGameModuleImpl, Cloudgarden, "Cloudgarden");
static FString GardenDataDir(){FString Directory;if(FParse::Value(FCommandLine::Get(),TEXT("CloudgardenDataDir="),Directory))return Directory;return FPaths::ProjectSavedDir();}
static double Num(const TSharedPtr<FJsonObject>& O,const TCHAR* K,double F=0){double V;return O.IsValid()&&O->TryGetNumberField(K,V)?V:F;}
static void ColorMesh(UStaticMeshComponent* Mesh,const FLinearColor& Color){auto Base=LoadObject<UMaterialInterface>(nullptr,TEXT("/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial"));if(Base){auto Material=Cast<UMaterialInstanceDynamic>(Mesh->GetMaterial(0));if(!Material)Material=UMaterialInstanceDynamic::Create(Base,Mesh);Material->SetVectorParameterValue(TEXT("Color"),Color);Mesh->SetMaterial(0,Material);}}
static FString Str(const TSharedPtr<FJsonObject>& O,const TCHAR* K,const FString& F=TEXT("—")){FString V;return O.IsValid()&&O->TryGetStringField(K,V)?V:F;}
ACloudgardenPlant::ACloudgardenPlant(){Mesh=CreateDefaultSubobject<UStaticMeshComponent>(TEXT("Plant"));RootComponent=Mesh;Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Cone.Cone")));Mesh->SetCollisionProfileName(TEXT("BlockAllDynamic"));}
void ACloudgardenController::BeginPlay(){Super::BeginPlay();bShowMouseCursor=true;SetInputMode(FInputModeGameAndUI());}
void ACloudgardenController::HandleHUDAction(const FString& Action,bool Keyboard){auto Mode=Cast<ACloudgardenMode>(GetWorld()->GetAuthGameMode());if(!Mode)return;if(Action==TEXT("details")){ShowDetails=!ShowDetails;ShowLibrary=false;InspectorScroll=0;}else if(Action==TEXT("library")){ShowLibrary=!ShowLibrary;ShowDetails=false;InspectorScroll=0;}else if(Action==TEXT("close")){ShowDetails=false;ShowLibrary=false;}else if(Action==TEXT("win"))Winners=true;else if(Action==TEXT("loss"))Winners=false;else if(Action.StartsWith(TEXT("window")))HistoryWindow=FCString::Atoi(*Action.Mid(6));else if(Action==TEXT("previous")){CatalogIndex=FMath::Max(0,CatalogIndex-1);InspectorScroll=0;}else if(Action==TEXT("next")){CatalogIndex++;InspectorScroll=0;}else if(Action==TEXT("collect"))Mode->CollectGene(CatalogIndex);else if(Action==TEXT("motion"))Mode->MotionEnabled=!Mode->MotionEnabled;else if(Action==TEXT("plane")){Mode->Plane=(Mode->Plane+1)%3;Mode->LastPayload.Empty();Mode->LoadSnapshot();}else Mode->SendCommand(Action);PanelProgress=Keyboard||!Mode->MotionEnabled||CloudgardenReducedMotion()?1.f:0.f;}
void ACloudgardenController::PlayerTick(float D){Super::PlayerTick(D);PanelProgress=FMath::Min(1.f,PanelProgress+D/.18f);auto Mode=Cast<ACloudgardenMode>(GetWorld()->GetAuthGameMode());if(!Mode)return;if(WasInputKeyJustPressed(EKeys::SpaceBar))HandleHUDAction(Mode->Playing?TEXT("pause"):TEXT("play"),true);if(WasInputKeyJustPressed(EKeys::Right))HandleHUDAction(TEXT("step"),true);if(WasInputKeyJustPressed(EKeys::P))HandleHUDAction(TEXT("plane"),true);if(WasInputKeyJustPressed(EKeys::M))HandleHUDAction(TEXT("motion"),true);if(WasInputKeyJustPressed(EKeys::G))HandleHUDAction(TEXT("library"),true);if(WasInputKeyJustPressed(EKeys::I))HandleHUDAction(TEXT("details"),true);if(WasInputKeyJustPressed(EKeys::Escape))HandleHUDAction(TEXT("close"),true);if(ShowLibrary&&WasInputKeyJustPressed(EKeys::Up))HandleHUDAction(TEXT("previous"),true);if(ShowLibrary&&WasInputKeyJustPressed(EKeys::Down))HandleHUDAction(TEXT("next"),true);if(ShowLibrary&&WasInputKeyJustPressed(EKeys::C))HandleHUDAction(TEXT("collect"),true);if(ShowDetails||ShowLibrary){if(WasInputKeyJustPressed(EKeys::MouseScrollDown))InspectorScroll+=3;if(WasInputKeyJustPressed(EKeys::MouseScrollUp))InspectorScroll=FMath::Max(0,InspectorScroll-3);if(WasInputKeyJustPressed(EKeys::PageDown))InspectorScroll+=8;if(WasInputKeyJustPressed(EKeys::PageUp))InspectorScroll=FMath::Max(0,InspectorScroll-8);}const bool Down=IsInputKeyDown(EKeys::LeftMouseButton);if(Down&&!WasDown){float X,Y;GetMousePosition(X,Y);bool Handled=false;for(auto& Action:HUDActions)if(Action.Bounds.IsInside(FVector2D(X,Y))){HandleHUDAction(Action.Action);Handled=true;break;}if(!Handled){FHitResult Hit;if(GetHitResultUnderCursor(ECC_Visibility,false,Hit)){Selected=Cast<ACloudgardenPlant>(Hit.GetActor());if(!Selected&&Hit.GetActor())Selected=Cast<ACloudgardenPlant>(Hit.GetActor()->GetOwner());ShowDetails=false;ShowLibrary=false;InspectorScroll=0;PanelProgress=Mode->MotionEnabled&&!CloudgardenReducedMotion()?0.f:1.f;}}}WasDown=Down;}
ACloudgardenMode::ACloudgardenMode(){PrimaryActorTick.bCanEverTick=true;PlayerControllerClass=ACloudgardenController::StaticClass();HUDClass=ACloudgardenHUD::StaticClass();DefaultPawnClass=nullptr;}
void ACloudgardenMode::BeginPlay(){Super::BeginPlay();FString CatalogText;if(FFileHelper::LoadFileToString(CatalogText,*(FPaths::ProjectContentDir()/TEXT("Data/GeneCatalog.json")))){auto CatalogReader=TJsonReaderFactory<>::Create(CatalogText);FJsonSerializer::Deserialize(CatalogReader,Catalog);}auto Camera=GetWorld()->SpawnActor<ACameraActor>();Camera->SetActorLocation(FVector(2200,-2200,2500));Camera->SetActorRotation((FVector(0,0,0)-Camera->GetActorLocation()).Rotation());Camera->GetCameraComponent()->ProjectionMode=ECameraProjectionMode::Orthographic;Camera->GetCameraComponent()->OrthoWidth=1400;GetWorld()->GetFirstPlayerController()->SetViewTarget(Camera);auto Light=GetWorld()->SpawnActor<ADirectionalLight>();Light->SetActorRotation(FRotator(-55,-30,0));Light->GetLightComponent()->SetIntensity(5);GetWorld()->SpawnActor<ASkyLight>();LoadSnapshot();if(auto PC=Cast<ACloudgardenController>(GetWorld()->GetFirstPlayerController());PC&&IsValid(PC->Selected)){FVector Target=PC->Selected->ExactAnchor+FVector(0,0,100);Camera->SetActorLocation(Target+FVector(1200,-1200,1250));Camera->SetActorRotation((Target-Camera->GetActorLocation()).Rotation());}GetWorldTimerManager().SetTimer(RefreshTimer,this,&ACloudgardenMode::LoadSnapshot,1,true);}
void ACloudgardenMode::SendCommand(const FString& Action){Playing=Action==TEXT("play")?true:Action==TEXT("pause")?false:Playing;const int64 Id=FDateTime::UtcNow().GetTicks();const FString Path=GardenDataDir()/TEXT("CloudgardenCommands.json");const FString Json=FString::Printf(TEXT("{\"id\":%lld,\"action\":\"%s\",\"days\":1}"),Id/10000,*Action);if(FFileHelper::SaveStringToFile(Json,*(Path+TEXT(".tmp"))))IFileManager::Get().Move(*Path,*(Path+TEXT(".tmp")),true);}
// Reuse native geometry by render slot: memory follows the maximum simultaneous garden, never elapsed days.
static TArray<AActor*> ShapePool;
static TArray<ACloudgardenPlant*> BotanicalPool;
static int ShapeCursor=0, BotanicalCursor=0;
static ACloudgardenPlant* BotanicalActor(UWorld* World){ACloudgardenPlant* Plant=nullptr;if(BotanicalPool.IsValidIndex(BotanicalCursor)&&IsValid(BotanicalPool[BotanicalCursor])&&BotanicalPool[BotanicalCursor]->GetWorld()==World)Plant=BotanicalPool[BotanicalCursor];else{Plant=World->SpawnActor<ACloudgardenPlant>();if(BotanicalPool.IsValidIndex(BotanicalCursor))BotanicalPool[BotanicalCursor]=Plant;else BotanicalPool.Add(Plant);}BotanicalCursor++;Plant->SetActorHiddenInGame(false);Plant->Mesh->SetCollisionEnabled(ECollisionEnabled::QueryOnly);return Plant;}
static AActor* Shape(UWorld* World,TArray<AActor*>& Store,const FVector& Location,const FVector& Scale,const TCHAR* Asset,const FLinearColor& Color){AActor* Actor=nullptr;UStaticMeshComponent* Mesh=nullptr;if(ShapePool.IsValidIndex(ShapeCursor)&&IsValid(ShapePool[ShapeCursor])&&ShapePool[ShapeCursor]->GetWorld()==World){Actor=ShapePool[ShapeCursor];Mesh=Cast<UStaticMeshComponent>(Actor->GetRootComponent());}else{Actor=World->SpawnActor<AActor>();Mesh=NewObject<UStaticMeshComponent>(Actor);Actor->SetRootComponent(Mesh);Mesh->RegisterComponent();if(ShapePool.IsValidIndex(ShapeCursor))ShapePool[ShapeCursor]=Actor;else ShapePool.Add(Actor);}ShapeCursor++;Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,Asset));Actor->SetActorHiddenInGame(false);Actor->SetOwner(nullptr);Actor->SetActorRotation(FRotator::ZeroRotator);ColorMesh(Mesh,Color);Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);Actor->SetActorLocation(Location);Actor->SetActorScale3D(Scale);Store.Add(Actor);return Actor;}
static void Segment(UWorld* World,TArray<AActor*>& Store,const FVector& A,const FVector& B,float Radius,const FLinearColor& Color){auto Actor=Shape(World,Store,(A+B)*.5,FVector(Radius,Radius,FVector::Dist(A,B)/100),TEXT("/Engine/BasicShapes/Cylinder.Cylinder"),Color);Actor->SetActorRotation(FQuat::FindBetweenNormals(FVector::UpVector,(B-A).GetSafeNormal()));}
void ACloudgardenMode::Tick(float Delta){Super::Tick(Delta);for(auto& F:Flights){if(!IsValid(F.Actor))continue;if(!MotionEnabled){F.Actor->SetActorLocation(F.To);continue;}F.Age+=Delta;float T=FMath::Clamp(F.Age/1.8f,0.f,1.f);F.Actor->SetActorLocation(FMath::Lerp(F.From,F.To,T)+FVector(0,0,FMath::Sin(T*PI)*90));}}
void ACloudgardenMode::CollectGene(int Index){const TArray<TSharedPtr<FJsonValue>>* Genes;if(!Catalog.IsValid()||!Catalog->TryGetArrayField(TEXT("genes"),Genes)||!Genes->IsValidIndex(Index))return;FString Text;TSharedPtr<FJsonObject> Collection=MakeShared<FJsonObject>();const FString Path=GardenDataDir()/TEXT("GeneCollection.json");if(FFileHelper::LoadFileToString(Text,*Path)){auto Reader=TJsonReaderFactory<>::Create(Text);FJsonSerializer::Deserialize(Reader,Collection);}TArray<TSharedPtr<FJsonValue>> Entries;const TArray<TSharedPtr<FJsonValue>>* Existing;if(Collection->TryGetArrayField(TEXT("genes"),Existing))Entries=*Existing;const FString Id=Str((*Genes)[Index]->AsObject(),TEXT("id"));for(auto Value:Entries)if(Str(Value->AsObject(),TEXT("id"))==Id){Status=TEXT("Gen ist bereits in deiner lokalen Sammlung.");return;}Entries.Add((*Genes)[Index]);Collection->SetArrayField(TEXT("genes"),Entries);Text.Empty();auto Writer=TJsonWriterFactory<>::Create(&Text);FJsonSerializer::Serialize(Collection.ToSharedRef(),Writer);FFileHelper::SaveStringToFile(Text,*Path);Status=TEXT("Einzelnes Gen lokal gesammelt. Dokumentation, keine Code-Ausfuehrung.");}
void ACloudgardenMode::LoadSnapshot(){
 FString Payload;const FString Path=GardenDataDir()/TEXT("CloudgardenSnapshot.json");if(!FFileHelper::LoadFileToString(Payload,*Path)){Status=TEXT("Keine Simulationsdaten. Lokale Replay-Bruecke starten.");return;}if(Payload==LastPayload)return;
 TSharedPtr<FJsonObject> Parsed;auto Reader=TJsonReaderFactory<>::Create(Payload);if(!FJsonSerializer::Deserialize(Reader,Parsed)||!Parsed.IsValid()){Status=TEXT("Ungueltiger Snapshot - letzter gueltiger Stand bleibt erhalten.");return;}
 FString SelectedId,SelectedGarden;auto Controller=Cast<ACloudgardenController>(GetWorld()->GetFirstPlayerController());if(Controller&&IsValid(Controller->Selected)){SelectedId=Controller->Selected->PlantId;SelectedGarden=Controller->Selected->GardenSymbol;}LastPayload=Payload;Snapshot=Parsed;Snapshot->TryGetBoolField(TEXT("playing"),Playing);
 for(auto Actor:Generated)if(IsValid(Actor)){Actor->SetActorHiddenInGame(true);Actor->SetActorEnableCollision(false);}Generated.Empty();Flights.Empty();ShapeCursor=0;BotanicalCursor=0;if(Controller)Controller->Selected=nullptr;
 const TArray<TSharedPtr<FJsonValue>>* Gardens;if(!Snapshot->TryGetArrayField(TEXT("gardens"),Gardens)){Status=TEXT("Snapshot enthaelt keine Gaerten.");return;}
 int GardenIndex=0;for(auto Value:*Gardens){auto Garden=Value->AsObject();const float Offset=Gardens->Num()==1?0:(GardenIndex++==0?-1050:1050);
 Shape(GetWorld(),Generated,FVector(Offset,0,-85),FVector(17,17,1.5),TEXT("/Engine/BasicShapes/Cube.Cube"),FLinearColor(.22,.28,.12));
 const float Ratio=Num(Garden,TEXT("nav"))/FMath::Max(1.,100+Num(Garden,TEXT("deposits")));const float WaterDepth=FMath::Clamp(28+76*(1-Ratio),12.,104.);
 Shape(GetWorld(),Generated,FVector(Offset,0,-WaterDepth),FVector(17.05,17.05,.06),TEXT("/Engine/BasicShapes/Cube.Cube"),FLinearColor(.24,.57,.59));
 Shape(GetWorld(),Generated,FVector(Offset,0,-3),FVector(17,17,.12),TEXT("/Engine/BasicShapes/Cube.Cube"),FLinearColor(.31,.42,.17));
 const TArray<TSharedPtr<FJsonValue>>* Plants;if(!Garden->TryGetArrayField(TEXT("plants"),Plants))continue;
 TArray<FVector> Crowns;TMap<FString,FVector> Anchors;TMap<FString,ACloudgardenPlant*> PlantActors;
 int Index=0;for(auto PV:*Plants){auto D=PV->AsObject();if(Str(D,TEXT("status"),TEXT("active"))!=TEXT("active"))continue;if(Index>=50)break;
 auto Plant=BotanicalActor(GetWorld());Plant->SetActorEnableCollision(true);Plant->Data=D;Plant->GardenSymbol=Str(Garden,TEXT("symbol"));Plant->PlantId=Str(D,TEXT("id"));Plant->PlantName=Str(D,TEXT("name"));
 double X=Num(D,Plane==1?TEXT("water"):TEXT("root"),.5),Y=Num(D,Plane==1?TEXT("sun"):TEXT("leaf"),.5);
 if(Plane==2){const TSharedPtr<FJsonObject>* T;if(D->TryGetObjectField(TEXT("tradingTraits"),T)){X=(Num(*T,TEXT("lookbackBars"),1)-1)/119.;Y=(Num(*T,TEXT("entryThresholdBps"),1)-1)/2999.;}else {X=.5;Y=.5;}}
 Plant->ExactAnchor=FVector(Offset+(X-.5)*1500,(Y-.5)*1500,0);FVector Crown=Plant->ExactAnchor;
 for(int Attempt=0;Attempt<300;Attempt++){bool Clear=true;for(const FVector& Other:Crowns)if(FVector::Dist2D(Crown,Other)<75){Clear=false;break;}if(Clear)break;const float Angle=(Attempt+1)*2.39996323f;const float Radius=30*FMath::Sqrt(float(Attempt+1));Crown=Plant->ExactAnchor+FVector(FMath::Cos(Angle)*Radius,FMath::Sin(Angle)*Radius,0);Crown.X=FMath::Clamp(Crown.X,Offset-810,Offset+810);Crown.Y=FMath::Clamp(Crown.Y,-810.,810.);}
 Crowns.Add(Crown);Plant->CrownOffset=Crown-Plant->ExactAnchor;Anchors.Add(Plant->PlantId,Plant->ExactAnchor);PlantActors.Add(Plant->PlantId,Plant);
 const float Biomass=FMath::Clamp(Num(D,TEXT("biomass")),0.,100.);const float Height=90+Biomass*3.6;const FString Form=Str(D,TEXT("phenotype"));
 const bool Cactus=Form==TEXT("Cactus");Plant->Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,TEXT("/Engine/BasicShapes/Cylinder.Cylinder")));
 ColorMesh(Plant->Mesh,Cactus?FLinearColor(.18,.43,.25):FLinearColor(.30,.42,.12));Plant->SetActorLocation(Crown+FVector(0,0,Height*.5));Plant->SetActorScale3D(FVector(Cactus?.15:.045,Cactus?.15:.045,Height/100));Generated.Add(Plant);
 Shape(GetWorld(),Generated,Plant->ExactAnchor+FVector(0,0,2),FVector(.28,.28,.025),TEXT("/Engine/BasicShapes/Cylinder.Cylinder"),FLinearColor(.48,.84,.66));Segment(GetWorld(),Generated,Plant->ExactAnchor,Crown+FVector(0,0,Height*.14),.055,FLinearColor(.28,.4,.13));
 const int LeafCount=Cactus?4:FMath::Clamp(FMath::RoundToInt(12+Biomass*.12),12,24);
 for(int Leaf=0;Leaf<LeafCount;Leaf++){
  const float Fraction=float(Leaf)/FMath::Max(1,LeafCount-1);const float Angle=Leaf*2.39996323f+Index*.3f;
  const FVector Direction(FMath::Cos(Angle),FMath::Sin(Angle),.12+.32*Fraction);
  const FVector Base=Crown+FVector(0,0,Height*(.13+.77*Fraction));
  const float Length=(28+Biomass*.55)*(1-.52*Fraction);const FVector Tip=Base+Direction*Length;
  auto Stalk=Shape(GetWorld(),Generated,(Base+Tip)*.5,FVector(Cactus?.065:.018,Cactus?.065:.018,FVector::Dist(Base,Tip)/100),TEXT("/Engine/BasicShapes/Cylinder.Cylinder"),FLinearColor(.27,.4,.12));Stalk->SetActorRotation(FQuat::FindBetweenNormals(FVector::UpVector,(Tip-Base).GetSafeNormal()));
  if(Cactus){Stalk->SetActorScale3D(FVector(.09,.09,FVector::Dist(Base,Tip)/100));continue;}
  // Two opposed tapered halves form a slender lanceolate leaf, rather than a sphere or a flat card.
  const FVector End=Tip+Direction*Length*.7;const FVector Middle=FMath::Lerp(Tip,End,.43f);
  for(int Half=0;Half<2;Half++){const FVector Point=Half==0?Tip:End;const FVector LeafDirection=(Point-Middle).GetSafeNormal();auto Blade=Shape(GetWorld(),Generated,(Point+Middle)*.5,FVector(Length*(Form==TEXT("Grass")?.10:.22)/100,.026,FVector::Dist(Point,Middle)/100),TEXT("/Engine/BasicShapes/Cone.Cone"),FLinearColor(.25+.08*Fraction,.44+.12*Fraction,.12+.03*Fraction));Blade->SetActorRotation(FQuat::FindBetweenNormals(FVector::UpVector,LeafDirection));Blade->SetOwner(Plant);Blade->SetActorEnableCollision(true);Cast<UStaticMeshComponent>(Blade->GetRootComponent())->SetCollisionEnabled(ECollisionEnabled::QueryOnly);Cast<UStaticMeshComponent>(Blade->GetRootComponent())->SetCollisionResponseToChannel(ECC_Visibility,ECR_Block);}
 }
 if(Controller&&((Plant->PlantId==SelectedId&&Plant->GardenSymbol==SelectedGarden)||(!IsValid(Controller->Selected)&&SelectedId.IsEmpty())))Controller->Selected=Plant;Index++;}
 const TArray<TSharedPtr<FJsonValue>>* Events;if(Garden->TryGetArrayField(TEXT("events"),Events))for(auto EV:*Events){auto E=EV->AsObject();if(Str(E,TEXT("type"))!=TEXT("conception")||Num(Garden,TEXT("day"))-Num(E,TEXT("day"))>1)continue;const FVector* Target=Anchors.Find(Str(E,TEXT("subject")));if(!Target)continue;FVector From(Offset-720,-720,80);const FVector* Parent=Anchors.Find(Str(E,TEXT("actor")));if(Parent)From=*Parent+FVector(0,0,100);FVector To=*Target+FVector(0,0,100);auto Bee=Shape(GetWorld(),Generated,From,FVector(.12,.12,.12),TEXT("/Engine/BasicShapes/Sphere.Sphere"),FLinearColor(.95,.72,.2));Flights.Add({Bee,From,To,0});}
 }
 Status=TEXT("P: Koordinatenebene | M: Bewegung | G: Genbibliothek | I: Pflanzenakte | PAPER ohne Boersenverbindung");
}
